  "set.th.hint": { en: "The defaults are <b>starting assumptions for small accounts</b> (under ~5K followers), calculated with the formulas above (Engagement Rate = interactions ÷ reach). For reference in 2025–26: median ER by reach is ~4–6% for Instagram Reels and ~5–8% for TikTok; follower conversion (new followers ÷ reach) is usually 0.1–0.5%, and 1% is already good. Adjust them once you have 10+ pieces of content with data — your own account's data always beats general benchmarks.", id: "Angka bawaan adalah <b>asumsi awal untuk akun kecil</b> (di bawah ±5K followers), dihitung dari rumus di atas (Engagement Rate = interaksi ÷ reach). Sebagai gambaran 2025–26: median ER berdasarkan reach untuk Reels Instagram ±4–6%, TikTok ±5–8%; konversi follower (follower baru ÷ reach) lazimnya 0,1–0,5%, dan 1% sudah bagus. Ubah setelah kamu punya 10+ konten dengan data — data akunmu sendiri selalu lebih tepat dari benchmark umum." },
  "set.th.appliesTo": { en: "Applies to", id: "Berlaku untuk" },
  "set.th.allPlatforms": { en: "All platforms (default)", id: "Semua platform (bawaan)" },
  "set.th.ownOverride": { en: "{platform} has its own thresholds — {platform} content is rated with the numbers below, not the defaults.", id: "{platform} punya ambang batas sendiri — konten {platform} dinilai dengan angka di bawah, bukan angka bawaan." },
  "set.th.usingDefault": { en: "{platform} still uses the defaults — change any number below to create thresholds just for {platform}.", id: "{platform} masih pakai angka bawaan — ubah salah satu angka di bawah untuk membuat ambang batas khusus {platform}." },
  "set.th.defaultNote": { en: "The defaults apply to every platform that doesn't have its own thresholds.", id: "Angka bawaan dipakai semua platform yang belum punya ambang batas sendiri." },
