  "pricing.founder.note": { en: "Lifetime credits are a monthly cap, not unlimited — that's what lets us keep this promise for good. Need more in a busy month? Top up anytime.", id: "Credit lifetime itu jatah per bulan, bukan unlimited — justru itu yang bikin janji \"selamanya\" ini bisa kami pegang. Bulan lagi rame? Tinggal top-up." },
  "pricing.addons.title": { en: "Add-ons", id: "Add-on" },
  "pricing.addons.sub": { en: "Only when you need them. Founder accounts buy extra brands right here; everything else is ordered via WhatsApp for now and added manually.", id: "Cuma kalau butuh. Akun Founder bisa beli tambahan brand langsung di sini; sisanya untuk sekarang pesan via WhatsApp dan kami tambahkan manual." },
  "pricing.addons.credits300": { en: "Top-up 300 AI credits", id: "Top-up 300 AI credit" },
  "pricing.addons.credits1000": { en: "Top-up 1,000 AI credits", id: "Top-up 1.000 AI credit" },
