  "pricing.hero.sub": { en: "Founder Lifetime costs about the same as {months} months of Pro. After that you pay nothing — same Pro features, for good.", id: "Founder Lifetime harganya setara {months} bulan langganan Pro. Setelah itu kamu nggak bayar apa-apa lagi — fitur Pro yang sama, selamanya." },
